"""Lược đồ dùng chung của ba tệp OpenAPI PH-19 và AsyncAPI (D03-04-PH19).

Tên trường JSON dùng camelCase, ánh xạ 1–1 với cột snake_case của D03-03-PH19.
Giá trị enum lấy đúng khung truy vết D02-03-PH19-00 §7, §9.3.
"""
R = lambda n: {"$ref": f"#/components/schemas/{n}"}


def s(type_, **kw):
    d = {"type": type_}; d.update(kw); return d


def obj(props, req=(), desc=None, extra=False, **kw):
    d = {"type": "object", "properties": props, "additionalProperties": extra}
    if req: d["required"] = list(req)
    if desc: d["description"] = desc
    d.update(kw); return d


def arr(items, **kw):
    d = {"type": "array", "items": items}; d.update(kw); return d


def enum(*v, desc=None):
    d = {"type": "string", "enum": list(v)}
    if desc: d["description"] = desc
    return d


def null(x):
    """Cho phép null (OpenAPI 3.1 / JSON Schema 2020-12)."""
    if "$ref" in x:
        return {"anyOf": [x, {"type": "null"}]}
    y = dict(x); y["type"] = [x["type"], "null"]; return y


STR = lambda mx=None, **kw: s("string", **({"maxLength": mx} if mx else {}), **kw)
INT = lambda **kw: s("integer", **kw)
BOOL = s("boolean")
TS = s("string", format="date-time")
DATE = s("string", format="date")
UUID = s("string", format="uuid")
ANYOBJ = {"type": "object", "additionalProperties": True}
CODE = STR(64, pattern="^[A-Z][A-Z0-9_-]{1,63}$")
CATCODE = STR(64, description="Mã mục danh mục PH-07.")
MONEY = R("Money")
OPT_MONEY = null(R("Money"))

